<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>英灵对话·雷恩</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: "Microsoft YaHei", sans-serif;
            background: transparent;
            padding: 10px;
        }

        .spirit-wrapper {
            display: flex;
            align-items: stretch;
            max-width: 650px;
            margin: 5px auto;
            background: linear-gradient(135deg, #1a1410 0%, #2a1f18 60%, #1e1612 100%);
            border: 1px solid #6b3a1f;
            border-left: 3px solid #8b4513;
            border-radius: 12px;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.4);
            overflow: hidden;
            animation: fadeIn 0.5s ease-in-out;
        }

        @keyframes fadeIn {
            from {
                opacity: 0;
                transform: translateY(10px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        /* ========== 左侧头像容器（取代原⚔️图标） ========== */
        .spirit-icon {
            flex-shrink: 0;
            width: 100px;
            /* 与其他角色统一 */
            display: flex;
            align-items: center;
            justify-content: center;
            background: rgba(139, 69, 19, 0.1);
            border-right: 1px solid rgba(139, 69, 19, 0.3);
            padding: 8px;
            transition: all 0.3s ease;
        }

        .spirit-icon img {
            display: block;
            width: 100%;
            height: auto;
            max-height: 90px;
            /* 与其他角色统一 */
            object-fit: contain;
            border-radius: 6px;
            image-rendering: auto;
            transition: transform 0.3s ease, opacity 0.4s ease;
            opacity: 0;
        }

        /* 图片加载成功淡入 */
        .spirit-icon img.img-loaded {
            opacity: 1;
        }

        /* 悬停时头像微动 */
        .spirit-wrapper:hover .spirit-icon img {
            transform: scale(1.08);
        }

        /* 图片加载失败隐藏整个头像区 */
        .spirit-icon.img-error {
            display: none;
        }

        /* ========== 对话内容区域 ========== */
        .spirit-dialogue {
            flex-grow: 1;
            padding: 18px 22px;
            /* 微调内边距，匹配更大的头像 */
            display: flex;
            flex-direction: column;
            justify-content: center;
            min-width: 0;
        }

        .spirit-name {
            font-size: 14px;
            /* 微调 */
            font-weight: bold;
            color: #c4713b;
            margin-bottom: 10px;
            letter-spacing: 1px;
        }

        .spirit-text {
            font-size: 14px;
            color: #d4c4b0;
            line-height: 1.8;
            word-wrap: break-word;
        }

        /* ========== 移动端适配 ========== */
        @media (max-width: 480px) {
            .spirit-wrapper {
                margin: 5px 0;
                border-radius: 10px;
            }

            .spirit-icon {
                width: 70px;
                padding: 6px;
            }

            .spirit-icon img {
                max-height: 62px;
                border-radius: 4px;
            }

            .spirit-dialogue {
                padding: 14px 16px;
            }

            .spirit-name {
                font-size: 13px;
            }

            .spirit-text {
                font-size: 13px;
            }
        }

        @media (max-width: 360px) {
            .spirit-icon {
                width: 56px;
                padding: 4px;
            }

            .spirit-icon img {
                max-height: 48px;
                border-radius: 3px;
            }

            .spirit-dialogue {
                padding: 10px 12px;
            }
        }
    </style>
</head>
<body>
